  'guide.revenue.title': 'महसूल वाटून घ्या',
  'guide.reports.title': 'अहवाल पहा',
  'guide.create.why': 'बाकी सर्व काही संस्थेशी जोडलेले आहे, म्हणून येथून सुरुवात करा. तुम्ही तिचे मालक होता.',
  'guide.venues.why': 'सत्रे, कोर्ट आणि शुल्क ठिकाणाशी जोडलेले असतात, म्हणून कार्यक्रम आखण्यापूर्वी तुमची प्रशिक्षण ठिकाणे जोडा.',
  'guide.staff.why': 'प्रशिक्षक, फ्रंट डेस्क आणि फायनान्सला स्वतंत्र प्रवेश द्या. प्रत्येकाला फक्त त्यांच्या भूमिकेला आवश्यक तेच दिसते.',
  'guide.suppliers.why': 'देखभाल कंत्राटदार आणि किट पुरवठादार एका जागी ठेवा, ते सेवा देत असलेल्या ठिकाणांशी जोडा आणि विनंत्या पूर्ण होईपर्यंत मागोवा घ्या.',
  'guide.programmes.why': 'कार्यक्रम म्हणजे कुटुंबे जे खरेदी करतात: संघ, सत्र अभ्यासक्रम किंवा शिबिर, किंमत आणि जागांसह.',
  'guide.coaches.why': 'प्रशिक्षकांना कर्मचारी, कंत्राटदार किंवा महसूल-भागीदार म्हणून घ्या आणि अटी लेखी ठरवा.',
  'guide.students.why': 'लोकांना चौकशीपासून नोंदणीपर्यंत न्या. मुलांसाठी पालक संमती देतात.',
  'guide.classes.why': 'आज आणि आठवडा एका नजरेत पहा, उपस्थिती नोंदवा आणि भरपाई व रद्द वर्ग दिसत ठेवा.',
  'guide.tax.why': 'जमा केलेला आणि भरलेला कर जाणून घ्या, तुमच्या कर नियमांसह आणि इनव्हॉइसवरील कर तपशीलांसह.',
  'guide.revenue.why': 'प्रशिक्षकांसोबत पैसे कसे वाटले जातात आणि सामायिक खर्च कार्यक्रमांमध्ये कसा विभागला जातो ते ठरवा.',
  'guide.reports.why': 'कार्यकारी होमवर निकाल, रिटेन्शन, आर्थिक स्थिती आणि भागीदार पहा आणि हवे ते एक्सपोर्ट करा.',
  'dp.tab': 'विकास योजना',
  'dp.title': 'खेळाडू विकास योजना',
  'dp.subtitle': 'प्रत्येक खेळाडूसाठी तांत्रिक, रणनीतिक, शारीरिक, मानसिक, शैक्षणिक आणि वैयक्तिक क्षेत्रांमध्ये एक हंगाम योजना. पुरावे त्यांच्या स्वतःच्या नोंदीतून वाचले जातात; काहीही कॉपी केले जात नाही किंवा एकत्र करून गुण दिला जात नाही.',
  'dp.family_subtitle': 'तुमची अकादमी तुमच्यासाठी ठेवत असलेली हंगाम योजना: कशावर काम सुरू आहे, कामे आणि तुम्ही वाचू शकता व प्रतिसाद देऊ शकता असे आढावे.',
  'dp.new_plan': 'नवीन योजना',
  'dp.create': 'योजना तयार करा',
  'dp.created': 'योजना तयार झाली. उद्दिष्टे जोडा, संघाला नाव द्या, मग ती सक्रिय करा.',
  'dp.new_notice': 'योजना एका हंगामासाठी एका खेळाडूभोवतीच्या लोकांमध्ये समन्वय साधते. ती प्रशिक्षण, उपस्थिती, शाळा आणि पाथवे नोंदींशी जोडली जाते; त्या कधीही कॉपी करत नाही.',
  'dp.search': 'खेळाडू किंवा हंगाम शोधा',
