  'arp.scope.academy': 'अकादमी',
  'arp.aud.progress': 'अकादमीचे मालक व प्रशासक, खेळाडूचा प्रशिक्षक, खेळाडू आणि पडताळलेले पालक वाचू शकतात. आर्थिक, वैद्यकीय किंवा कल्याण नोंदी, तसेच प्रशिक्षक व कर्मचाऱ्यांचा खासगी अभिप्राय कधीही समाविष्ट नसतो.',
