  'nav.title.AcademyAudits': 'माझ्याकडे नेमलेले ऑडिट',
  'acc.mine_title': 'माझ्याकडे नेमलेले ऑडिट',
  'acc.mine_sub': 'ज्या ऑडिटमध्ये तुमचे नाव निरीक्षक म्हणून आहे',
  'acc.mine_card_sub': 'निरीक्षक म्हणून तुमच्याकडे {n} ऑडिट नेमले आहेत',
  'acc.mine_empty_title': 'कोणतेही ऑडिट नेमलेले नाही',
  'acc.mine_empty_sub': 'एखाद्या अकादमीने तुम्हाला निरीक्षक म्हणून नेमले की ऑडिट येथे दिसेल.',
  'guide.accreditation.title': 'मान्यता आणि ऑडिट व्यवस्थापित करा',
  'guide.accreditation.why': 'तुमच्या अकादमीकडे असलेली प्रत्येक बाह्य मान्यता, परवाना आणि गुणवत्ता चिन्ह यांचा मागोवा घ्या, प्रत्येकाचा पुरावा तुम्ही आधीच सांभाळत असलेल्या नोंदींशी जोडून ठेवा आणि गुपचूप बदलता न येणाऱ्या निष्कर्षांसह व सुधारात्मक कृतींसह ऑडिट चालवा.',
  'guide.accreditation.s1': 'अकादमी उघडा, मग मान्यता, आणि फ्रेमवर्क जोडण्यासाठी कॉन्फिगर करा वर टॅप करा: मान्यता देणारी संस्था, प्रकार, स्तर, जबाबदार व्यक्ती, नूतनीकरण चक्र आणि स्मरणाचा कालावधी.',
  'guide.accreditation.s2': 'फ्रेमवर्क उघडा, पुरावा निवडा, त्याला काय आवश्यक आहे ते जोडा, मग प्रशिक्षक पात्रता आणि अनुपालन नोंदी जोडा. काहीही कॉपी केले जात नाही आणि वैधता थेट वाचली जाते.',
  'guide.accreditation.s3': 'ऑडिट नियोजित करा वर टॅप करा, प्रकार, तारीख आणि पडताळणीची क्षेत्रे निवडा, आणि हवे असल्यास निरीक्षक नेमा, ज्याला फक्त तेच ऑडिट दिसते.',
  'guide.accreditation.s4': 'प्रत्येक निष्कर्ष त्याच्या गंभीरतेसह आणि सुधारात्मक कृतींसह नोंदवा, प्रत्येक कृतीला जबाबदार व्यक्ती आणि देय तारीख द्या, आणि काम पूर्ण होताच त्या पूर्ण म्हणून चिन्हांकित करा.',
  'guide.accreditation.s5': 'सर्व उच्च आणि मध्यम निष्कर्षांचे निराकरण झाल्यावर पुन्हा सादर करा, मग निरीक्षकाचा निर्णय नोंदवा. प्रत्येक पायरी लॉक केलेल्या नोंदीत जतन केली जाते.',
