  'inc.a_signed': 'मंजूर केले',
  'inc.lvl_emerging': 'उदयोन्मुख',
  'inc.lvl_developing': 'विकसनशील',
  'inc.lvl_secure': 'स्थिर',
  'inc.lvl_exceeding': 'अपेक्षेपेक्षा अधिक',
  'guide.inclusion.title': 'सर्वसमावेशक आणि अनुकूलित कार्यक्रम चालवा',
  'guide.inclusion.why': 'दिव्यांग आणि पॅरा खेळाडूंना निदान न सांगता तुमच्या कार्यक्रमांत सहभागी होता यावे आणि प्रगती करता यावी यासाठी: कार्यक्रम काय देतो ते ठरवा, प्रत्येक अनुकूलित सत्र तयार आहे का ते तपासा आणि खेळाडूंना त्यांनी निवडलेल्या कार्यात्मक गरजाच सामायिक करू द्या.',
  'guide.inclusion.s1': 'अकादमी, मग समावेश, मग कार्यक्रम सेटअप उघडा, एक कार्यक्रम निवडा आणि कोण सहभागी होऊ शकते, खेळानुसार अनुकूलन साचे, दिले जाणारे बदल, स्थळ सुविधा आणि आवश्यक सहाय्यक व्यक्ती प्रमाण निवडा.',
  'guide.inclusion.s2': 'स्थळ व्यवस्थापकांना प्रत्येक स्थळाच्या सुलभता सुविधा (लिफ्ट, पायऱ्या नसलेला मार्ग, सुलभ चेंजिंग रूम, पूल हॉइस्ट) नोंदवायला सांगा, म्हणजे सत्रे त्यांच्याशी पडताळता येतील.',
  'guide.inclusion.s3': 'खेळाडू, किंवा तरुण खेळाडूचे सत्यापित पालक, माझी अकादमी, मग सोयी-सुविधा उघडतात आणि कर्मचाऱ्यांना जे हवे तेच, कोणाशी आणि कधीपर्यंत सामायिक करतात. ते कधीही मागे घेता येते.',
  'guide.inclusion.s4': 'समावेश, मग सत्र सज्जता उघडा, एक सत्र निवडा आणि प्रत्येक उणीव दूर करा: स्थळ, सहाय्यक व्यक्ती, कर्तव्य व्याप्ती आणि मुख्य प्रशिक्षकाचे प्रमाणपत्र. प्रशिक्षक आणि स्थळ कर्मचाऱ्यांना फक्त त्यांच्याशी सामायिक केलेलेच दिसते आणि प्रत्येक पाहणी खेळाडूसाठी नोंदवली जाते.',
  'guide.inclusion.s5': 'वर्णनात्मक पातळ्यांसह, प्रशिक्षकाच्या नेतृत्वाखालील अनुकूलित मूल्यमापन नोंदवा, कधीही एकच गुण नाही, आणि दुसऱ्या मूल्यमापनकर्त्याकडून मंजुरी घ्या. संचालकांना आढावा पानावर फक्त संख्या दिसते.',


